<script setup>
import { ref, computed, watch, onMounted, onUnmounted } from 'vue';
import { useRouter } from 'vue-router';
import { api, role, label, time } from './api';
const router = useRouter(), contracts = ref([]), catalog = ref([]), busy = ref(false), showUpload = ref(false), query = ref(''), state = ref(''), source = ref(''), intakeMode = ref(''), type = ref(''), reviewer = ref(''), reviewers = ref([]), page = ref(1), total = ref(0);
const files = ref([]), form = ref({ ourEntity: '', perspective: '', purpose: '' }), completed = ref(0);
const filtered = computed(() => contracts.value);
const enabledTypes = computed(() => catalog.value.flatMap(c=>c.types).filter(t=>t.reviewEnabled).map(t=>t.name).join('、'));
const trialTypes = computed(() => catalog.value.flatMap(c=>c.types).filter(t=>t.trialAvailable).map(t=>t.name).join('、'));
const stats = computed(() => [{ name: '筛选结果', n: total.value }, { name: '本页待法务处理', n: contracts.value.filter(c => ['pending_review', 'in_review'].includes(c.legal_status) && c.review?.status === 'completed').length }, { name: '本页 AI 正在处理', n: contracts.value.filter(c => ['queued', 'running'].includes(c.review?.status)).length }, { name: '本页需补件 / 处理', n: contracts.value.filter(c => ['waiting_input', 'failed'].includes(c.review?.status)).length }]);
const typeName = id => catalog.value.flatMap(c => c.types).find(t => t.id === id)?.name || '待确认分类';
let loadSequence = 0;
async function load(quiet = false) { const sequence = ++loadSequence; const params = new URLSearchParams({view:'main',page:String(page.value),q:query.value,status:state.value,source:source.value,intakeMode:intakeMode.value,type:type.value,reviewer:reviewer.value}); for (const [key,value] of [...params]) if (!value) params.delete(key); const data = await api('/contracts?'+params, { quiet }); if (sequence === loadSequence) { contracts.value = data.items; total.value = data.total; } }
let searchTimer;
watch([query,state,source,intakeMode,type,reviewer], () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => { if (page.value !== 1) page.value = 1; else load().catch(()=>{}); }, 250); });
watch(page, () => load().catch(()=>{}));
function selectFiles(e) { files.value = [...e.target.files]; }
async function upload() { busy.value = true; completed.value = 0; try { for (const file of files.value) { const data = new FormData(); data.set('file', file); data.set('background', JSON.stringify(form.value)); await api('/contracts/upload', { method: 'POST', body: data }); completed.value++; } showUpload.value = false; files.value = []; await load(); } finally { busy.value = false; } }
let timer;
onMounted(async () => { await load(); catalog.value = (await api('/catalog')).categories; if (role('legal')) reviewers.value = await api('/reviewers'); timer = setInterval(() => load(true).catch(() => {}), 5000); }); onUnmounted(() => { clearInterval(timer); clearTimeout(searchTimer); });
</script>
<template>
  <section class="page-heading"><div><div class="eyebrow">CONTRACT WORKSPACE</div><h1>合同与待办</h1><p>从接收到归档，跟踪每一份合同的审查进度。</p></div><div class="action-row"><router-link v-if="role('legal')" to="/reconciliation" class="secondary-link">补查待确认</router-link><button v-if="role('business','legal')" class="primary" @click="showUpload = true">＋ 提交合同</button></div></section>
  <div class="stat-grid"><div v-for="(s,i) in stats" :key="s.name" class="stat-card"><span>{{ s.name }}</span><strong>{{ s.n.toString().padStart(2,'0') }}</strong><i :class="'stat-line line-'+i"></i></div></div>
  <div class="panel"><div class="panel-heading"><h2>合同台账 <span class="count">{{ total }}</span></h2><button class="text-btn" @click="load()">↻ 刷新</button></div><div class="filter-row"><input v-model="query" class="search" placeholder="搜索合同名称、编号…" aria-label="搜索合同" /><select v-model="state" aria-label="法务状态"><option value="">全部法务状态</option><option v-for="s in ['pending_review','in_review','returned','finalized','archived']" :value="s" :key="s">{{ label(s) }}</option></select><select v-model="source" aria-label="来源"><option value="">全部来源</option><option value="manual">手动上传</option><option value="dingtalk">钉钉审批</option></select><select v-model="intakeMode" aria-label="收件方式"><option value="">全部收件方式</option><option value="live">实时收件</option><option value="reconciliation">历史补查</option><option value="manual">手动上传</option></select><select v-model="type" aria-label="合同类型"><option value="">全部合同类型</option><option v-for="t in catalog.flatMap(c=>c.types)" :value="t.id" :key="t.id">{{ t.name }}</option></select><select v-if="role('legal')" v-model="reviewer" aria-label="负责人"><option value="">全部负责人</option><option value="unassigned">未分配</option><option v-for="u in reviewers" :key="u.id" :value="u.id">{{ u.displayName }}</option></select></div>
    <div class="table-scroll"><table><thead><tr><th>合同名称 / 编号</th><th>合同类型</th><th>收件方式</th><th>AI 处理</th><th>法务流程</th><th>提交时间</th><th></th></tr></thead><tbody><tr v-for="c in filtered" :key="c.id" @click="router.push('/contracts/'+c.id)" class="clickable"><td><strong class="contract-title">{{ c.title }}</strong><small class="mono">{{ c.number }}</small></td><td>{{ typeName(c.classification?.typeId) }}<small v-if="!c.classification?.confirmed" class="muted">尚未人工确认</small></td><td><span class="badge" :class="c.intake_mode">{{ c.intake_mode==='live'?'实时收件':c.intake_mode==='reconciliation'?'历史补查':'手动上传' }}</span></td><td><span class="badge" :class="c.review?.status">{{ label(c.review?.status) }}</span><small v-if="c.review?.snapshot?.reviewMode==='trial'">示例规则试审</small><small v-if="c.review?.status==='running'">{{ c.review.progress }}%</small></td><td><span class="badge" :class="c.legal_status">{{ label(c.legal_status) }}</span></td><td class="muted nowrap">{{ time(c.created_at) }}</td><td class="arrow">↗</td></tr></tbody></table></div>
    <div v-if="!filtered.length" class="empty-state"><span class="empty-icon">▤</span><h3>{{ contracts.length?'没有符合条件的合同':'合同工作空间已就绪' }}</h3><p>{{ contracts.length?'调整筛选条件查看其他合同。':'提交 PDF 或 DOCX，开始创建不可变的文件版本。' }}</p><button v-if="role('business','legal') && !contracts.length" @click="showUpload=true">提交第一份合同</button></div>
  </div><div class="action-row" style="justify-content:flex-end;margin:16px 0"><span class="muted">共 {{ total }} 份 · 第 {{ page }} / {{ Math.max(1,Math.ceil(total/50)) }} 页</span><button :disabled="page<=1" @click="page--">上一页</button><button :disabled="page*50>=total" @click="page++">下一页</button></div><div class="notice subtle">正式预审类型：{{ enabledTypes || '尚无已发布的专项规则' }}。示例试审类型：{{ trialTypes || '暂无' }}。其他类型发布适用专项规则后即可启用；试审结果需由法务核对。</div>
  <el-dialog v-model="showUpload" title="提交合同" width="580px" :close-on-click-modal="!busy"><form @submit.prevent="upload" class="stack"><div class="notice">每个文件分别创建合同任务。补充材料请在审核详情中上传，避免误建为主合同。</div><label class="drop-zone">选择 PDF / DOCX（每份 ≤ 50MB）<input type="file" multiple accept=".pdf,.docx" required @change="selectFiles" /><span v-if="files.length">已选 {{ files.length }} 份</span></label><label>我方主体<input v-model="form.ourEntity" required placeholder="公司完整名称" /></label><label>我方交易立场<input v-model="form.perspective" required placeholder="例如：采购方 / 委托仓储方" /></label><label>交易目的<textarea v-model="form.purpose" required rows="3" placeholder="简述交易内容及需要重点关注的问题" /></label><div class="dialog-actions"><span class="muted" v-if="busy">已提交 {{ completed }} / {{ files.length }}</span><button class="primary" :disabled="busy || !files.length">{{ busy?'正在提交…':'提交并开始预审' }}</button></div></form></el-dialog>
</template>
